-- Explicit V1 exception authorized by the operator: persisted bootstrap ROOT.
create table authorization_permissions(id bigint generated by default as identity primary key,code varchar(100) not null unique,description varchar(255) not null,module varchar(40) not null,created_at timestamptz not null default current_timestamp);
create table authorization_roles(id bigint generated by default as identity primary key,name varchar(100) not null unique,active boolean not null,created_at timestamptz not null default current_timestamp);
create table authorization_role_permissions(id bigint generated by default as identity primary key,role_id bigint not null references authorization_roles(id),permission_id bigint not null references authorization_permissions(id),created_at timestamptz not null default current_timestamp,unique(role_id,permission_id));
create table authorization_identity_roles(identity_id uuid not null references ima_identities(id) on delete cascade,role_id bigint not null references authorization_roles(id),scope varchar(20) not null default 'PLATFORM' check(scope='PLATFORM'),created_at timestamptz not null default current_timestamp,primary key(identity_id,role_id));
